steps.snippet:
name_parts = str(binding["name"]).split()
if not name_parts:
    raise ValueError("binding['name'] must contain at least one token for the first name")

first_name = name_parts[0]

idx = device.find(hint="First name", editable=True)
if idx is None:
    idx = device.find(text="First name", editable=True)
if idx is None:
    raise RuntimeError("Could not find the editable First name field")

device.input_text(first_name, index=idx)

idx = device.find(hint="Last name", editable=True)
if idx is None:
    idx = device.find(text="Last name", editable=True)
if idx is None:
    raise LookupError("Last name field not found")

if len(binding["name"].split()) < 2:
    raise ValueError("binding['name'] must contain a first and last name")

device.input_text(binding["name"].split()[1], index=idx)

save = device.find(text="Save", clickable=True)
if save is None:
    save = device.find(description="Save", clickable=True)
if save is None:
    raise RuntimeError("Save button not found")
device.click(index=save)

parts = binding['name'].split()
if len(parts) < 2:
    raise ValueError("binding['name'] must contain a last name: binding['name'].split()[1] is unavailable")

last_name = parts[1]
idx = device.find(hint='Last name', editable=True)
if idx is None:
    idx = device.find(text='Last name', editable=True)
if idx is None:
    idx = device.find(contains='Last name', editable=True)
if idx is None:
    raise RuntimeError("Could not find the editable 'Last name' field")

device.input_text(last_name, index=idx)

number = binding.get('number')
if number is None:
    raise RuntimeError("Missing binding['number']")

idx = device.find(hint='Phone', editable=True)
if idx is None:
    idx = device.find(text='Phone', editable=True)
if idx is None:
    idx = device.find(contains='Phone', editable=True)
if idx is None:
    raise RuntimeError("Could not find editable 'Phone' field")

device.input_text(str(number), index=idx)

parts = binding["name"].split()
if len(parts) < 2:
    raise ValueError("binding['name'] must include a last name token")

last_name = parts[1]
idx = device.find(text="Last name", hint="Last name", editable=True)
if idx is None:
    idx = device.find(contains="Last name", editable=True)
if idx is None:
    raise ValueError("Could not find editable Last name field")

device.input_text(last_name, index=idx)

phone_index = device.find(hint='Phone', editable=True)
if phone_index is None:
    phone_index = device.find(text='Phone', editable=True)
if phone_index is None:
    raise RuntimeError("Could not find an editable Phone field")
device.input_text(binding['number'], index=phone_index)
